                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SQCOM_REPLEN_UPLOAD_FORMAT AS WITH replen_output AS ( SELECT branch_code, sku, facility, allocated_units FROM qcom_inventory_loss_sale_replen WHERE allocated_units > 0 QUALIFY ROW_NUMBER() OVER ( PARTITION BY SKU, branch_code, facility ORDER BY allocated_units DESC ) = 1 ), MAX_ORDER_NUM AS ( SELECT MAX(RIGHT(order_name, 5)) AS order_name_max FROM ( SELECT *, TRY_TO_DATE(\"DATE\", \'DD/MM/YYYY\') AS converted_date FROM snitch_db.maplemonk.GS_B2B_UC WHERE \"DATE\" != \'.\' AND TRY_TO_DATE(\"DATE\", \'DD/MM/YYYY\') >= \'2025-11-25\' ) ), STORE_DETAILS_UC AS ( SELECT * FROM SNITCH_DB.MAPLEMONK.GS__SO_IMPORT_MASTER ), COST_PRICE_MAPPING AS ( SELECT sku, MAX(cost_price) AS cost_price FROM SNITCH_DB.MAPLEMONK.UC_FINAL_ITEM_MASTER GROUP BY 1 ), SO_number_prep AS ( SELECT r.*, LPAD( TO_VARCHAR( COALESCE(m.order_name_max, 0) + CASE r.facility WHEN \'SAPL-WH2\' THEN 1 WHEN \'SAPL-WH1\' THEN 2 WHEN \'SAPL-NORTH-TAURU\' THEN 3 ELSE 0 END ), 5, \'0\' ) AS so_number_5d FROM replen_output r CROSS JOIN MAX_ORDER_NUM m ), store_details_join AS ( SELECT p.*, uc.so_code, uc.store_name, CONCAT( \'QC-\', CASE WHEN LOWER(TRIM(uc.so_code)) = \'hrbrla\' THEN \'KALYAN\' ELSE COALESCE(uc.so_code, \'\') END, COALESCE(p.so_number_5d, \'\') ) AS so_code_so_number, CASE WHEN UPPER(TRIM(uc.store_name)) ILIKE \'%FOCO%\' THEN cosp.cost_price * 1.25 ELSE cosp.cost_price END AS cost_price FROM SO_number_prep p LEFT JOIN STORE_DETAILS_UC uc ON p.branch_code = uc.store_code LEFT JOIN COST_PRICE_MAPPING cosp ON LOWER(TRIM(p.SKU)) = LOWER(TRIM(cosp.sku)) ), store_details_join_seq AS ( SELECT sdj.*, ROW_NUMBER() OVER ( PARTITION BY sdj.so_code_so_number ORDER BY sdj.SKU, sdj.branch_code, sdj.facility ) AS item_seq FROM store_details_join sdj ), FINAL_OUTPUT AS ( SELECT sdj.so_code_so_number AS \"Sales Order Code*\", sdj.so_code_so_number AS \"Display Sales Order Code\", uc.EMAIL_ID AS \"Notification Email\", NULL AS \"Notification Mobile\", 1 AS \"COD*\", uc.CHANNEL AS \"Channel\", NULL AS \"Priority\", uc.STORE_CODE AS \"Shipping Address Id\", uc.SHIPPING_ADDRESS_NAME AS \"Shipping Address Name\", uc.SHIPPING_ADDRESS_LINE_2 AS \"Shipping Address Line 1\", uc.COMPANY_NAME AS \"Shipping Address Line 2\", uc.SHIPPING_ADDRESS_CITY AS \"Shipping Address City\", uc.SHIPPING_ADDRESS_STATE AS \"Shipping Address State\", uc.SHIPPING_ADDRESS_COUNTRY AS \"Shipping Address Country\", uc.SHIPPING_ADDRESS_PINCODE AS \"Shipping Address Pincode\", NULL AS \"Shipping Address Latitude\", NULL AS \"Shipping Address Longitude\", uc.SHIPPING_ADDRESS_PHONE AS \"Shipping Address Phone\", uc.BILLING_ADDRESS_ID AS \"Billing Address Id\", uc.BILLING_ADDRESS_NAME AS \"Billing Address Name\", uc.BILLING_ADDRESS_LINE_1 AS \"Billing Address Line 1\", uc.BILLING_ADDRESS_LINE_2 AS \"Billing Address Line 2\", uc.BILLING_ADDRESS_CITY AS \"Billing Address City\", uc.BILLING_ADDRESS_STATE AS \"Billing Address State\", \'IN\' AS \"Billing Address Country\", uc.BILLING_ADDRESS_PINCODE AS \"Billing Address Pincode\", NULL AS \"Billing Address Latitude\", NULL AS \"Billing Address Longitude\", uc.BILLING_ADDRESS_PHONE AS \"Billing Address Phone\", NULL AS \"Combination Identifier\", NULL AS \"Combination Description\", CONCAT(sdj.so_code_so_number, sdj.item_seq) AS \"Sale Order Item Code*\", \'STD\' AS \"Shipping Method*\", sdj.SKU AS \"Item SKU Code*\", NULL AS \"Channel Product Id\", NULL AS \"Item Name\", NULL AS \"Requires Customization\", NULL AS \"Gift Wrap\", uc.ACC_CODE AS \"Gift Message*\", sdj.cost_price AS \"Selling Price\", 0 AS \"Discount\", 0 AS \"Shipping Charges\", NULL AS \"Shipping Method Charges\", NULL AS \"COD Service Charges\", NULL AS \"Gift Wrap Charges\", NULL AS \"Voucher Code\", NULL AS \"Voucher Value\", NULL AS \"Store Credit\", NULL AS \"Packet Number\", NULL AS \"On Hold\", NULL AS \"Order Date as dd/mm/yyyy hh:MM:ss\", NULL AS \"Channel Order Processing Date as dd/MM/yyyy hh:mm:ss\", NULL AS \"Shipping